def parse_range(spec):
    """Parse "1-5" or a bare "3" into a list of ints.

    Both ends of a range are included. A descending range such as "5-1" counts
    down.
    """
    if "-" not in spec:
        return [int(spec)]
    a, b = spec.split("-")
    a, b = int(a), int(b)
    if a <= b:
        return list(range(a, b + 1))
    else:
        return list(range(a, b - 1, -1))
